const tabId = 118779795;
const textSlice = await browserjs(tabId, () => {
  const main = document.querySelector('main') || document.querySelector('article') || document.body;
  const elements = Array.from(main.querySelectorAll('h2, h3, p, ul'));
  return elements.map(el => ({
    tag: el.tagName,
    text: el.innerText.trim()
  }));
});

// Let's filter and inspect the Symptoms and Causes sections
const relevant = [];
let capture = false;
for (const el of textSlice) {
  if (el.tag === 'H2' && el.text.includes('Symptoms')) {
    capture = true;
  }
  if (capture) {
    relevant.push(`${el.tag}: ${el.text}`);
    if (el.tag === 'H2' && el.text.includes('Complications')) {
      break;
    }
  }
}

console.log(relevant.join('\n\n'));

