const tabId = 118779795;
const overview = await browserjs(tabId, () => {
  const h2s = Array.from(document.querySelectorAll('h2'));
  const overviewH2 = h2s.find(h => h.textContent.trim().toLowerCase() === 'overview');
  if (!overviewH2) return null;
  let text = '';
  let sibling = overviewH2.nextElementSibling;
  while (sibling && sibling.tagName !== 'H2') {
    text += sibling.innerText + '\n\n';
    sibling = sibling.nextElementSibling;
  }
  return text;
});

console.log("Overview text:\n", overview);

const tabId = 118779795;
const overviewContent = await browserjs(tabId, () => {
  const h2s = Array.from(document.querySelectorAll('h2'));
  const overviewH2 = h2s.find(h => h.textContent.trim().toLowerCase() === 'overview');
  if (!overviewH2) return 'No overview H2';
  // Check parent or container
  return overviewH2.parentElement?.innerText || 'No parent';
});

console.log("Overview section:\n", overviewContent.slice(0, 1000));

const tabId = 118779795;
const topText = await browserjs(tabId, () => {
  const article = document.querySelector('article') || document.querySelector('main');
